/** Compute Entrypoint Contract
  *
  * guarantee REQUEST_QUALIFICATION_TOTAL
  *   Both request fields determine the validity-aware qualified request
  * @param api_request_sample incoming data port
  * @param api_qualified_request outgoing data port
  */
pub fn compute_spec_REQUEST_QUALIFICATION_TOTAL_guarantee(
  api_request_sample: Drone_Lifecycle_Governor::Lifecycle_Request_Sample,
  api_qualified_request: Drone_Lifecycle_Governor::Qualified_Request) -> bool
{
  api_qualified_request == qualify_request(api_request_sample)
}

